def cc(n):
    s = ''
    while n != 0:
        s = str(n % 3) +  s
        n //= 3
    return s

def f(n):
    s = cc(n)
    sum_digits = sum(map(int,list(s)))
    if sum_digits % 4 == 0:
        s = s.replace('1','*').replace('2','1').replace('*','2')
        s = '10' + s
    else:
        s += '20'
        s = s[0] + '02' + s[3:]
    return int(s,3)

mi = float('inf')
ans = 0
for i in range(1,100000):
    if f(i) > 302:
        if mi >= f(i):
            mi = f(i)
            ans = i
print(ans)
